#!/usr/bin/env bash
# Tests for the compose file generated by wsl/lib/providers.sh.
# Guards the contract that MinIO and SeaweedFS are opt-in AND never start with the machine.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
source "$ROOT/wsl/lib/logging.sh"
source "$ROOT/wsl/lib/providers.sh"

PASS=0
FAIL=0
assert() { # assert <description> <command...>
  local desc="$1"; shift
  if "$@"; then
    PASS=$((PASS + 1)); echo "  ok   $desc"
  else
    FAIL=$((FAIL + 1)); echo "  FAIL $desc"
  fi
}

contains() { [[ "$1" == *"$2"* ]]; }
has_line() { grep -qxF -- "$2" <<< "$1"; }
not_contains() { [[ "$1" != *"$2"* ]]; }

# Returns the YAML block of one compose service (from "  name:" to the next service/top-level key).
service_block() { # service_block <file> <service>
  awk -v svc="  $2:" '
    $0 == svc { on = 1; print; next }
    on && /^  [a-z_-]+:$/ { exit }
    on && /^[a-z]/ { exit }
    on { print }
  ' "$1"
}

generate() { # generate <skip_minio> <skip_seaweedfs> [skip_ollama]
  SKIP_POSTGRES=true SKIP_VALKEY=false SKIP_PGADMIN=true SKIP_PORTAINER=false
  SKIP_MINIO=$1 SKIP_SEAWEEDFS=$2 SKIP_OLLAMA=${3:-true}
  D="$(mktemp -d)"
  mkdir -p "$D/providers/postgres/init" "$D/providers/valkey" "$D/providers/pgadmin" "$D/providers/seaweedfs"
  _providers_write_compose "$D"
  _providers_write_configs "$D" >/dev/null 2>&1
}

echo "defaults (flags as in setup-wsl.sh)"
generate true true
compose="$(cat "$D/docker-compose.yml")"
assert "MinIO is not generated by default"       not_contains "$compose" "container_name: minio"
assert "SeaweedFS is not generated by default"   not_contains "$compose" "container_name: seaweedfs"
assert "no seaweedfs volume by default"          not_contains "$compose" "seaweedfs_data"
assert "Ollama is not generated by default"      not_contains "$compose" "container_name: ollama"
assert "no s3.json written by default"          [ ! -f "$D/providers/seaweedfs/s3.json" ]
assert "Valkey is generated"                     contains "$compose" "container_name: valkey"
assert "Valkey uses the valkey/valkey image"     contains "$compose" "image: valkey/valkey:"
assert "Redis is gone from the compose file"     not_contains "$compose" "redis"
assert "valkey.conf written"                     [ -f "$D/providers/valkey/valkey.conf" ]
assert "no redis.conf written"                   [ ! -e "$D/providers/redis" ]
assert ".env uses VALKEY_PORT"                   contains "$(cat "$D/.env")" "VALKEY_PORT=6379"
rm -rf "$D"

echo "with --with-minio --with-seaweedfs"
generate false false
for svc in minio seaweedfs; do
  block="$(service_block "$D/docker-compose.yml" "$svc")"
  assert "$svc is generated"                              contains "$block" "container_name: $svc"
  assert "$svc is in its own compose profile"             has_line "$block" "      - $svc"
  assert "$svc has profiles: (not started by up -d)"      has_line "$block" "    profiles:"
  assert "$svc does not restart on boot (restart: \"no\")" has_line "$block" '    restart: "no"'
done
assert "seaweedfs_data volume declared"  contains "$(cat "$D/docker-compose.yml")" "  seaweedfs_data:"
assert "s3.json written"                 [ -f "$D/providers/seaweedfs/s3.json" ]
assert "s3.json has an access key"       contains "$(cat "$D/providers/seaweedfs/s3.json")" "accessKey"
assert ".env documents SeaweedFS ports"  contains "$(cat "$D/.env")" "SEAWEEDFS_S3_PORT=8333"

echo "with --with-ollama"
generate true true false
block="$(service_block "$D/docker-compose.yml" ollama)"
assert "ollama is generated"                     contains "$block" "container_name: ollama"
assert "ollama is in its own compose profile"    has_line "$block" "      - ollama"
assert "ollama does not restart on boot"         has_line "$block" '    restart: "no"'
assert "ollama joins the shared network"         has_line "$block" "      - shared-network"
assert "ollama_data volume declared"             contains "$(cat "$D/docker-compose.yml")" "  ollama_data:"
assert "no models are pulled by the compose"     not_contains "$block" "pull"
rm -rf "$D"

generate false false
echo "re-run keeps edited s3.json credentials"
sed -i 's/seaweedadmin/mycustomkey/' "$D/providers/seaweedfs/s3.json"
SKIP_POSTGRES=true SKIP_VALKEY=false SKIP_PGADMIN=true SKIP_PORTAINER=false SKIP_MINIO=false SKIP_SEAWEEDFS=false SKIP_OLLAMA=true
_providers_write_configs "$D" >/dev/null 2>&1
assert "edited credentials preserved"    contains "$(cat "$D/providers/seaweedfs/s3.json")" "mycustomkey"
rm -rf "$D"

echo "deprecated --skip-redis alias"
out="$(grep -- '--skip-redis)' "$ROOT/wsl/setup-wsl.sh")"
assert "--skip-redis still maps to SKIP_VALKEY" contains "$out" "SKIP_VALKEY=true"
echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
